using System;
using System.Collections.Generic;
using Microsoft.Web.Administration;
using Microsoft.Web.Management.Server;
namespace JexusManager.Features.MimeMap { internal sealed class MimeMapService : ModuleService { [ModuleServiceMethod] public MimeMapItem[] GetItems() { var result = new List<MimeMapItem>(); foreach (ConfigurationElement e in Collection()) result.Add(new MimeMapItem { FileExtension = (string)e["fileExtension"], MimeType = (string)e["mimeType"], Flag = e.IsLocallyStored ? "Local" : "Inhertied" }); return result.ToArray(); } [ModuleServiceMethod] public void Add(MimeMapItem item) { AddItem(Collection(), item); ManagementUnit.Update(); } [ModuleServiceMethod] public void Update(MimeMapItem oldItem, MimeMapItem item) { var c = Collection(); var e = Find(c, oldItem); if (e != null) c.Remove(e); AddItem(c, item); ManagementUnit.Update(); } [ModuleServiceMethod] public void Remove(MimeMapItem item) { var e = Find(Collection(), item) ?? throw new InvalidOperationException("MIME map was not found."); Collection().Remove(e); ManagementUnit.Update(); } private ConfigurationElementCollection Collection() => ManagementUnit.Configuration.GetSection("system.webServer/staticContent").GetCollection(); private static ConfigurationElement Find(ConfigurationElementCollection c, MimeMapItem i) { foreach (ConfigurationElement e in c) if ((string)e["fileExtension"] == i.FileExtension) return e; return null; } private static void AddItem(ConfigurationElementCollection c, MimeMapItem i) { if (i == null || string.IsNullOrWhiteSpace(i.FileExtension)) throw new ArgumentException("A file extension is required."); var e = c.CreateElement(); e["fileExtension"] = i.FileExtension; e["mimeType"] = i.MimeType; c.Add(e); } } }
